      fields: [u => ({ id: 'grade', label: 'الصف الدراسي الحالي', options: GRADES, value: GRADES[Math.min(11, Math.max(0, u.age - 6))] }), u => ({ id: 'gov', label: 'محافظة المدرسة المحوَّل إليها', options: govList(), value: u.gov }), { id: 'adm', label: 'الإدارة التعليمية', test: G.minLen(3), msg: 'اكتب اسم الإدارة التعليمية.' }, { id: 'type', label: 'نوع المدرسة المطلوبة', options: SCH_TYPES }, { id: 'school', label: 'اسم المدرسة المحوَّل إليها', test: G.minLen(4), msg: 'اكتب اسم المدرسة.' }, { id: 'why', label: 'سبب التحويل', options: ['تغيير محل الإقامة', 'قرب المدرسة من السكن', 'ظروف صحية', 'ظروف أسرية', 'أخرى'] }],
